@js:
    java.toast("正在努力加载中，请稍后");

var sort = [];
var push = (title, url, type1, type2) => {
    sort.push ({
        title: title,
        url: url,
        style: {
            layout_flexGrow: type1,
            layout_flexBasisPercent: type2
        }
    });
};

var x = [{
        u: "http://m.xxxbiquge.net/xclass/0/1.html",
        ti: "༺ˇ»`类型分类´«ˇ༻",
        reb: /(\d+)\.html/,
        rea: "{{page}}.html"
    },
    {
        u: "http://m.xxxbiquge.net/quanben.html",
        ti: "༺ˇ»`全本分类´«ˇ༻",
        reb: /(.*)\.html/,
        rea: "$1_{{page}}.html"
    },
    {
        u: "http://m.xxxbiquge.net/ph/week.html",
        ti: "༺ˇ»`周榜´«ˇ༻",
        reb: /(.*)\.html/,
        rea: "$1_{{page}}.html"
    },
    {
        u: "http://m.xxxbiquge.net/ph/month0.html",
        ti: "༺ˇ»`月榜´«ˇ༻",
        reb: /(.*)\.html/,
        rea: "$1_{{page}}.html"
    },
    {
        u: "http://m.xxxbiquge.net/ph/all0.html",
        ti: "༺ˇ»`总榜´«ˇ༻",
        reb: /(.*)\.html/,
        rea: "$1_{{page}}.html"
    }];

x.forEach (i => {
    var o = org.jsoup.Jsoup.parse(java.ajax(i.u));
    var s = o.select('nav.sortChannel_nav>a');
    push(i.ti, "", 1, 1);
    s.forEach(j => {
        var url = String (j.attr("href")).replace(i.reb,i.rea);
        push(j.text(), url, 1, 0.25)
    })
});

JSON.stringify(sort);

